import React from 'react'

class Lis extends React.Component {
    names = [
        {
            'name': 'God',
            'profession': 'Undefined'
        },
        {
            'name': 'joel',
            'profession': 'hacker'
        },
    ]


    render() {
        display = () => {
            this.names.map((name, profession) => {
               return (
                <>
                 <h1>{name}</h1>    <p>{profession}</p>
                </>
               )
            })
        }
    }
}

export default Lis
